# KubeJS 神秘农业

该项目有两个目标：替代神秘定制化功能，并支持所有神秘农业的配方类型。

通过本项目，您可以添加觉醒配方、附魔师配方、灌注配方、种子再处理配方、灵魂提取配方和灵魂合金刷怪笼配方。

本模组为作物和生物灵魂类型提供了启动事件，允许访问相应的注册表，这意味着您可以添加作物和生物灵魂。

### 添加配方
```javascript
ServerEvents.recipes(event => {
const {awakening,enchanter,infusion,reprocessor,soul_extraction,soulium_spawner} = event.recipes.mysticalagriculture;

    // 觉醒配方
    awakening(
        "minecraft:gold_ingot", // 产物
        "minecraft:iron_ingot", // 中心物品
        [
            Item.of("minecraft:yellow_dye",40), // 可包含数量
            Item.of("minecraft:yellow_dye",40),
            Item.of("minecraft:yellow_dye",40),
            Item.of("minecraft:yellow_dye",40)
        ], // 精华容器中的物品
        [
            "#minecraft;flowers",
            "#minecraft;flowers",
            "#minecraft;flowers",
            "#minecraft;flowers",
        ] // 基座上的物品
    );
    // 附魔师配方
    enchanter(
        "minecraft:sharpness", // 产出的附魔
        [
            Item.of("minecraft:flint",3),
            Item.of("minecraft:iron_ingot",2)
        ] // 1-2个物品的数组，可包含数量
    );
    // 灌注配方
    infusion(
        "minecraft:emerald", // 产物
        "minecraft:diamond", // 中心物品
        [
            Item.of("minecraft:green_dye",4) // 数量会展开为多个物品
        ] // 基座上的物品
    );
    // 再处理器配方
    reprocessor(
        "minecraft:iron_ingot", // 产物
        "minecraft:compass" // 输入物品
    );
    // 灵魂提取配方
    // 构造方式1
    soul_extraction(
        {
            type:"mysticalagriculture:blaze", 
            souls:30
        }, // 生物灵魂
        "minecraft:magma_cream" // 输入物品
    );
    // 构造方式2
    soul_extraction(
        "mysticalagriculture:zombie", // 生物灵魂类型
        0.5, // 灵魂数量
        "minecraft:diamond" // 输入物品
    );
    // 灵魂合金刷怪笼配方
    soulium_spawner(
        [
            { 
                entity:"minecraft:zombie",
                weight:100
            },
            {
                entity:"minecraft:iron_golem",
                // 未定义权重时默认为1
            }
        ], // 实体列表
        [
            Item.of("minecraft:emerald",4) // 可包含数量
        ] // 输入物品
    );
});
```

### 添加作物

在启动脚本中
```javascript
MysticalAgricultureStartupEvents.crop(event => {
    // 此处可通过 event.registry 访问作物注册表
    /* 可用方法 
    void register(Crop crop);
    void registerTier(CropTier tier);
    void registerType(CropType type);
    List<Crop> getCrops();
    Crop getCropById(ResourceLocation id);
    Crop getCropByName(String name);
    List<CropTier> getTiers();
    CropTier getTierById(ResourceLocation id);
    List<CropType> getTypes();
    CropType getTypeById(ResourceLocation id);
    */
    // 注意：无法注销作物，但可以禁用它们
    // 注册作物需要创建 Crop 对象
    const kubium = new Crop(
        "kubejs:kubium", // 作物ID
        "mysticalagriculture:5", // 作物等级ID或对象
        "mysticalagriculture:resource", // 作物类型ID或对象
        new CropTextures(
            "mysticalagriculture:block/flower_ingot",// 花朵纹理
            "mysticalagriculture:item/essence_ingot" // 精华纹理
            // 可通过额外参数设置种子纹理
        ), // 纹理设置
        "#forge:ingots/kubium" // 原料，注意这是神秘农业使用的自定义对象，必须是标签或物品
    );
    const red = new Crop(
        "kubejs:red",
        CropTier.ONE,
        CropType.RESOURCE,
        CropTextures.DUST_CROP_TEXTURES,
        16711680,// 十进制颜色值
        "minecraft:red_dye"
    );
    // 创建作物后进行注册
    event.register(kubium);
    red.setDisplayName(Text.ofString("RED").red());
    event.register(red);
});
```

